window.ELITE_GUIDE={"version":"2.02","weapons":[{"id":"shock","name":"Shock Rifle","tag":"Movement rewards","summary":"Combos use a 50–210 raw damage curve, 390-UU outer radius and movement bonuses.","rows":[{"label":"Weapon raise time","b19":"0.30 s","elite":"0.41 s","note":"Raise time is the time to equip this weapon; lower time is the time to put it away. Firing cooldown can delay a switch."},{"label":"Movement damage bonuses","b19":"None","elite":"Nice +10 / Amazing +15 / Spectacular +20 damage","note":"Constant eligible own-core additions to raw damage, capped at 210."},{"label":"Foreign-core feedback","b19":"No Anticombo notice","elite":"Anticombo!","note":"Foreign cores receive no movement bonus."},{"label":"Combo raw damage / blast radii","b19":"40–210 · 77/390 UU","elite":"50–210 · 77/390 UU","note":"Before movement bonuses and any tapered base boost."},{"label":"Combo falloff exponent","b19":"1.5","elite":"1.5","note":"Applied between the inner and outer radii."},{"label":"Base combo bonus","b19":"None","elite":"None","note":"No separate base boost."},{"label":"Core firing interval","b19":"0.45 s","elite":"0.49451 s","note":"91% of B19 fire rate."},{"label":"Refire switching multiplier","b19":"0.08","elite":"0.15","note":"Dimensionless multiplier used by firing-state switching."},{"label":"Own-core notice eligibility","b19":"Native awards","elite":"Confirmed enemy health/armor loss or credited kill","note":"The v1.76 revision changed feedback eligibility, not damage."},{"label":"Foreign-core kill feed","b19":"Native combo label","elite":"Anticombo label and Denied voice","note":"Final v1.67 restores normal switching and adds the dedicated kill-feed label."},{"label":"Attack interactions (v1.8 policy)","b19":"Native behavior","elite":"Native projectile predicates govern rocket, Flak and Bio contacts, with reciprocal native Shock-core handling. Default rocket/core and Flak/core pairs remain ignored. Rockets and rocket grenades ignore both Weapon and WeaponNoCharacter traces on main and assist colliders; landed goo uses native shootable collision and native damage response. Other Shock exclusions remain.","note":"Contact predicates, component collision and damage response are separate gates."},{"label":"Weapon icon defaults","b19":"Original colors","elite":"Explicit Elite10K colors restored","note":"Independent HUD palettes can override presentation."}],"notes":["Raw combo damage ranges from 50 to 210 within 390 UU, with full damage inside 77 UU and falloff exponent 1.5.","No separate base boost is applied.","Own-core movement adds Nice +10, Amazing +15 or Spectacular +20, with a 210 cap. A foreign core receives no movement bonus.","Core interval 0.49451 s; switching multiplier 0.15.","Own-core notices use confirmed enemy health/armor loss. Credited kills show red, confirmed damage yellow, and live no-damage notices are suppressed.","Foreign-core notice: Anticombo!."],"lab":"shock"},{"id":"flak","name":"Flak Cannon","tag":"Native time decay","summary":"Native time-decaying primary shards: 10.4/20.8 damage to 4/8, with decay over approximately 1–2 tuning dodge distances.","rows":[{"label":"Primary firing interval","b19":"0.80 s","elite":"0.90 s","note":"Secondary remains 0.97 s.","stock":"0.80 s","utplus":"0.90 s"},{"label":"Primary shard speed","b19":"≈18.67 dodge lengths/s (13,000 UU/s)","elite":"≈18.67 dodge lengths/s (13,000 UU/s)","note":"Same projectile speed as B19.","stock":"Inherited native speed; no component override","utplus":"Central initial 7,000 UU/s; ordinary speed inherited"},{"label":"Primary projectile count","b19":"8 ordinary + 1 central","elite":"8 ordinary + 1 central","note":"","stock":"Not separately verified","utplus":"Not separately verified"},{"label":"Primary damage model","b19":"Damage decreases with flight time; central-hit bonus","elite":"Native flight-time decay","note":"No custom travelled-distance accumulator or impact damage rewrite.","stock":"Native flight-time decay and central-hit bonus","utplus":"Native flight-time decay and central-hit bonus"},{"label":"Bounce damage multiplier","b19":"0.65×","elite":"1×","note":"B19 uses 0.65× when the native gravity/bounce branch applies: 16×0.65 = 10.4 and 32×0.65 = 20.8 before per-hit truncation. B19 flight-time rules differ.","stock":"0.60×","utplus":"0.60×"},{"label":"Shard hit momentum","b19":"Native momentum","elite":"Native B19 momentum","note":"Custom zero-momentum hit handling removed.","stock":"Ordinary 17,000; central inherited","utplus":"Ordinary 17,000 / central 29,000"},{"label":"Ball collision radius","b19":"30 UU","elite":"13 UU","note":"Physical collision, not splash radius.","stock":"Not separately verified","utplus":"Not separately verified"},{"label":"Ball initial speed","b19":"≈4.67 dodge lengths/s (3,250 UU/s)","elite":"3,055 UU/s (94% of B19)","note":"94% of authoritative B19 launch speed; 22.2% faster than Stock/UT+.","stock":"2,500 UU/s","utplus":"2,500 UU/s"},{"label":"Ball maximum speed","b19":"≈9.88 dodge lengths/s (6,880 UU/s)","elite":"6,467.2 UU/s (94% of B19)","note":"94% of authoritative B19 maximum speed; 7.79% higher cap than Stock/UT+.","stock":"6,000 UU/s","utplus":"6,000 UU/s"},{"label":"Secondary firing interval","b19":"0.97 s","elite":"0.97 s","note":"","stock":"1.00 s","utplus":"1.00 s"},{"label":"Weapon raise time","b19":"0.29 s","elite":"0.41 s","note":"Raise time is the time to equip this weapon; lower time is the time to put it away. Firing cooldown can delay a switch.","stock":"0.50 s","utplus":"0.30 s"},{"label":"Ball base splash damage","b19":"95","elite":"95","note":"","stock":"Inherited native maximum","utplus":"115"},{"label":"Ball splash damage / blast radii","b19":"95 max / 20 min · 0–300 UU","elite":"95 max / 35 min · 0–240 UU","note":"Native linear splash.","stock":"Inherited native damage; 40–330 UU","utplus":"115 max / 18 min; inner 20 UU; outer inherited"},{"label":"Primary range damage","b19":"Native behavior","elite":"10.4/20.8 → 4/8 by projectile age","note":"Decay starts near 0.053846 s and reaches the floor near 0.107692 s. At constant 13,000 UU/s this is 700–1,400 UU (1–2 tuning dodge distances of 700 UU). Actual impacts depend on age, not accumulated path distance.","stock":"Not separately verified","utplus":"Not separately verified"},{"label":"Primary hit acceptance","b19":"Native behavior","elite":"Native projectile checks; extra geometric filter removed","note":"","stock":"Not separately verified","utplus":"Not separately verified"},{"label":"Explosion handling","b19":"Native explosion","elite":"Native explosion path","note":"Legacy projectile cutoff is disabled.","stock":"Native explosion","utplus":"Native explosion"},{"label":"Flight smoke opacity","b19":"Original effect","elite":"0.2 · half of earlier opacity","note":"The visible M_Rocket_trail_01 layer; all emitters retained.","stock":"Not separately verified","utplus":"Not separately verified"},{"label":"Explosion effect asset","b19":"Original effect","elite":"Restored explosion particle asset","note":"v1.58 restores the packaged effect; v1.62 temporarily uses an earlier build base.","stock":"Not separately verified","utplus":"Not separately verified"},{"label":"Attack interactions (v1.8 policy)","b19":"Native behavior","elite":"Native projectile predicates govern rocket, Flak and Bio contacts, with reciprocal native Shock-core handling. Default rocket/core and Flak/core pairs remain ignored. Rockets and rocket grenades ignore both Weapon and WeaponNoCharacter traces on main and assist colliders; landed goo uses native shootable collision and native damage response. Other Shock exclusions remain.","note":"Contact predicates, component collision and damage response are separate gates.","stock":"Not separately verified","utplus":"Not separately verified"},{"label":"Weapon icon defaults","b19":"Original colors","elite":"Explicit Elite10K colors restored","note":"Independent HUD palettes can override presentation.","stock":"Not separately verified","utplus":"Not separately verified"},{"label":"Shredded award requirements","b19":"Native Shredded qualification","elite":"Native B19 qualification","note":"Custom central-plus-seven/all-nine tracker removed; native center MaxShreddedTime is 0.15 game seconds.","stock":"Not separately verified","utplus":"Not separately verified"},{"label":"Shard visual sizing","b19":"Original shard visuals","elite":"Original shard visuals","note":"The dynamic sphere-matching experiment was reverted in final v1.82.","stock":"Not separately verified","utplus":"Not separately verified"},{"label":"Applied initial ordinary / central damage","b19":"Native behavior","elite":"10 / 20","note":"Enemy effective initial damage is 10 / 20 before armor.","stock":"Not separately verified","utplus":"Not separately verified"},{"label":"Primary self damage","b19":"Native behavior","elite":"Stored base 10.4/20.8; up to 100 before self attenuation","note":"Self damage uses a separate native branch, bypassing enemy multiplier/floors. Shipping minimum is one per shard; 25 damage/s attenuation starts after 0.11 s.","stock":"Not separately verified","utplus":"Not separately verified"},{"label":"Primary stored base / minimum","b19":"Ordinary base 16 / minimum 8; central base 32 / minimum 5","elite":"Ordinary 10.4 / 4; central 20.8 / 8","note":"Each hit is truncated separately when applied to a character. Eight full ordinary hits plus a full central hit produce 8×10 + 20 = 100 before armor or other modifiers.","stock":"Ordinary base 11; central base 12; minima inherited","utplus":"Ordinary base 11; central base 13 / minimum 6; ordinary minimum inherited"}],"notes":["Primary interval 0.90 s, secondary 0.97 s. Each shot contains eight ordinary shards and one central shard; the central shard deals double damage.","Primary projectiles directly inherit native Flak shard classes. Custom distance, body-hit and Shredded tracker helpers are removed.","Enemy ordinary/central damage starts at 10.4/20.8 and decays with age to 4/8 between approximately 0.053846 and 0.107692 game seconds. Native hit position and other modifiers still apply.","700–1,400 UU is only the straight-flight equivalent at 13,000 UU/s, not an accumulated path-distance rule.","Native Shredded qualification and native momentum are restored. Secondary ball geometry, damage and speed are unchanged.","Primary shard speed is 13,000 UU/s. The secondary ball collision radius is 13 UU; its initial/maximum speeds are 3,055/6,467.2 UU/s. Ball-spawned shards are separate from the primary model.","Native splash: 95 max, 35 minimum, 0/240 UU inner/outer radii. Values are before armor and other modifiers.","The 10.4/20.8 bases provide fractional headroom before truncation; 100 is not guaranteed once decay starts or when some shards miss. The final v2.0 endpoint is approximately 2 tuning dodge distances of 700 UU.","Compared with both Stock and UT+, the 10K ball launches 22.2% faster (3,055 vs 2,500 UU/s) and has a 7.79% higher cap (6,467.2 vs 6,000 UU/s)."],"lab":"flak","comparisonColumns":[{"key":"stock","label":"Stock UT"},{"key":"utplus","label":"UT+"},{"key":"b19","label":"Original B19"},{"key":"elite","label":"Elite10K v2.02"}],"comparisonStyle":"projectile","variantScope":"Stock values come from the base-game weapon/projectile assets. UT+ uses UT+FlakCannon and UTPlusRocketLauncher in UTPlus-WindowsNoEditor.pak (SHA256 208D9D6EFA99D6EF92C7905A6BA2F2482391C909206CD1669494EA6EB500310E). “Not separately verified” means no numerical comparison is claimed. Server replacements and NCP variants are separate."},{"id":"rocket","name":"Rocket Launcher","tag":"Volley pacing","summary":"Loaded volleys use a 1.05-second base refire interval with native splash.","rows":[{"label":"Primary interval","b19":"1.05 s","elite":"1.05 s","note":"","stock":"Not separately verified","utplus":"Not separately verified"},{"label":"Secondary refire / 1 rocket","b19":"0.74 s","elite":"1.05 s","note":"Default fire-rate multiplier; no additional delay for extra loaded rockets.","stock":"Not separately verified","utplus":"Not separately verified"},{"label":"Secondary refire / 2 rockets","b19":"0.74 s","elite":"1.05 s","note":"Default fire-rate multiplier; no additional delay for extra loaded rockets.","stock":"Not separately verified","utplus":"Not separately verified"},{"label":"Secondary refire / 3 rockets","b19":"0.74 s","elite":"1.05 s","note":"Default fire-rate multiplier; no additional delay for extra loaded rockets.","stock":"Not separately verified","utplus":"Not separately verified"},{"label":"Delay between rockets in a volley","b19":"0.015 s","elite":"Native B19 volley scheduling","note":"Custom volley scheduling removed; native loading/firing retained.","stock":"Not separately verified","utplus":"Not separately verified"},{"label":"Normal rocket initial / maximum speed","b19":"3,200 / 5,200 UU/s","elite":"2,912 / 4,732 UU/s · 91% of B19","note":"Both normal rocket speeds are 91% of authoritative B19; acceleration remains 600 UU/s². Seeking rockets and rocket grenades retain their prior settings.","stock":"2,750 / 2,750 UU/s","utplus":"2,750 / 2,950 UU/s"},{"label":"Seeking initial / maximum speed","b19":"2,000 / 2,200 UU/s","elite":"1,800 / 2,160 UU/s · 90% of B19","note":"Both launch speed and maximum speed are 10% lower than B19.","stock":"2,000 / 2,200 UU/s","utplus":"2,200 / 2,600 UU/s"},{"label":"Grenade initial / maximum speed","b19":"1,900 / 3,000 UU/s","elite":"1,900 / 3,000 UU/s · 100% of B19","note":"Launch speed and maximum speed are unchanged. These are Rocket Launcher grenades.","stock":"Not separately verified","utplus":"2,000 / 3,000 UU/s"},{"label":"Weapon raise / lower time","b19":"0.47 / 0.08 s","elite":"0.41 / 0.08 s","note":"Raise time is the time to equip this weapon; lower time is the time to put it away. Firing cooldown can delay a switch. Loaded rocket/grenade volleys finish firing before a queued switch; switching back does not skip the remaining cooldown.","stock":"Inherited native times","utplus":"Raise 0.30 s; lower inherited"},{"label":"Splash damage / blast radii","b19":"100 max / 20 min · 15–360 UU","elite":"100 max / 35 min · 15–296.66666 UU","note":"Native linear splash.","stock":"Inherited native damage and radii","utplus":"Inherited native damage / inner radius; outer 345 UU"},{"label":"Cooldown bar","b19":"B19 weapon HUD","elite":"Red loading rings; native white dots hidden","note":"During release each spent ring clears from the actual remaining loaded count. Remaining rings continue the existing grace depletion.","stock":"Not separately verified","utplus":"Not separately verified"},{"label":"Explosion handling","b19":"Native explosion","elite":"Native explosion path","note":"Legacy projectile cutoff is disabled.","stock":"Native explosion","utplus":"Native explosion"},{"label":"Loaded volley switching deadline","b19":"Original firing state","elite":"Native firing state plus pending-switch retry","note":"Retries an existing valid pending switch after the volley finishes. No custom firing deadline, refire calculation or EarliestFireTime write.","stock":"Not separately verified","utplus":"Not separately verified"},{"label":"Projectile shell design","b19":"Original projectile art","elite":"Final merged shell and native rear blend","note":"Visual-only revisions.","stock":"Not separately verified","utplus":"Not separately verified"},{"label":"Unused material cleanup","b19":"Original package contents","elite":"Obsolete runtime overrides removed; appearance preserved","note":"v1.69 removes unused material data without changing gameplay or the approved appearance.","stock":"Not separately verified","utplus":"Not separately verified"},{"label":"Attack interactions (v1.8 policy)","b19":"Native behavior","elite":"Native projectile predicates govern rocket, Flak and Bio contacts, with reciprocal native Shock-core handling. Default rocket/core and Flak/core pairs remain ignored. Rockets and rocket grenades ignore both Weapon and WeaponNoCharacter traces on main and assist colliders; landed goo uses native shootable collision and native damage response. Other Shock exclusions remain.","note":"Contact predicates, component collision and damage response are separate gates.","stock":"Not separately verified","utplus":"Not separately verified"},{"label":"Weapon icon defaults","b19":"Original colors","elite":"Explicit Elite10K colors restored","note":"Independent HUD palettes can override presentation.","stock":"Not separately verified","utplus":"Not separately verified"},{"label":"Rocket grenade art","b19":"Original grenade art","elite":"Finished regular-rocket shell and coating","note":"Rocket grenades share the regular rocket mesh; size, collision and damage are unchanged.","stock":"Not separately verified","utplus":"Not separately verified"},{"label":"Loading ring size","b19":"Native behavior","elite":"95% of final v1.96 size at default radius scale","note":"Final v1.98 default size retained. Local radius scale 0–1.75 and opacity 0–1; either zero hides custom rings.","stock":"Not separately verified","utplus":"Not separately verified"},{"label":"Loaded inventory safety","b19":"Native behavior","elite":"Internal rocket helper weapons excluded","note":"The configured launcher remains available; final v1.87 fixes the Loaded-command helper grant.","stock":"Not separately verified","utplus":"Not separately verified"},{"label":"Early-selected grenade refire / 1, 2, 3 grenades","b19":"0.74 s secondary base interval","elite":"1.05 / 0.895 / 0.74 s","note":"Select grenade mode while native loading is preparing an attack, before the full load and first shot. Late or uncertain selection retains 1.05 s. Regular rocket volleys remain 1.05 s. Loading time is separate.","stock":"Not separately verified","utplus":"Not separately verified"}],"notes":["Loaded volleys of one, two or three rockets use the same 1.05-second base refire interval. Loading time and native scheduling are separate.","Loading rings show progress and how many rockets are ready. A bright red center marks a loaded rocket; a brief pulse marks completion. The rocket’s red panels and metal collar help it stand out to other players.","Native splash: 100 max, 35 minimum, 15/296.66666 UU inner/outer radii. Values are before armor and other modifiers.","Rocket grenades use the same finished shell and red coating as regular rockets. This changes appearance only.","The rocket spins about its centered visual axis.","Firing a single loaded rocket starts the HUD ring fade immediately, preventing a lingering red ring.","Normal rockets use 2,912/4,732 UU/s initial/maximum speed, 91% of B19’s 3,200/5,200; acceleration is 600 UU/s².","The configured launcher uses native B19 loading and firing with 1.05-second secondary refire, 0.41-second equip time, and a pending-switch retry after a completed volley. No custom firing deadline is added.","Early-selected grenade volleys use 1.05 / 0.895 / 0.74 s recovery for 1 / 2 / 3 grenades. Late or uncertain selection falls back to 1.05 s; switching back to regular rockets restores regular timing. Real client/server checks passed at measured 312/624 ms with fixed delay; loss/jitter, queued switches and changing fire-rate cases remain unverified.","Normal 10K rockets launch 5.89% faster than Stock and UT+ (2,912 vs 2,750 UU/s). Their cap is 60.41% higher than UT+ (4,732 vs 2,950) and 72.07% higher than Stock (4,732 vs 2,750). Caps are not constant flight speeds: 10K acceleration is 600 UU/s²; UT+ explicitly sets 50 UU/s²."],"lab":"rocket","comparisonColumns":[{"key":"stock","label":"Stock UT"},{"key":"utplus","label":"UT+"},{"key":"b19","label":"Original B19"},{"key":"elite","label":"Elite10K v2.02"}],"comparisonStyle":"projectile","variantScope":"Stock values come from the base-game weapon/projectile assets. UT+ uses UT+FlakCannon and UTPlusRocketLauncher in UTPlus-WindowsNoEditor.pak (SHA256 208D9D6EFA99D6EF92C7905A6BA2F2482391C909206CD1669494EA6EB500310E). “Not separately verified” means no numerical comparison is claimed. Server replacements and NCP variants are separate."},{"id":"stinger","name":"Stinger","tag":"Burst reserve","summary":"Native shot scheduling with 0.475-second full-burst recovery; recovery freezes throughout secondary and primary fire.","rows":[{"label":"Primary damage","b19":"12","elite":"11","note":""},{"label":"Primary interval","b19":"0.088 s","elite":"0.088 s","note":""},{"label":"Secondary projectile base damage","b19":"10","elite":"10","note":""},{"label":"Opening sequence length","b19":"12 projectiles","elite":"10 projectiles","note":""},{"label":"Opening potential / all hits","b19":"120 damage","elite":"100 damage","note":""},{"label":"Opening first-to-last shot span","b19":"≈0.379 s","elite":"≈0.379 s","note":""},{"label":"Sustained secondary interval","b19":"0.148 s","elite":"0.148 s","note":""},{"label":"Secondary ammo per projectile","b19":"2","elite":"2","note":""},{"label":"Recovery after a full opening burst","b19":"B19 firing cycle; no separate reserve cooldown","elite":"0.475 s from the last actual secondary shot","note":"Recovery is revealed after the expected next-shot interval plus one update confirms quiet, then credits elapsed quiet time retrospectively. Native state timing and update quantization still apply."},{"label":"Weapon raise / lower time","b19":"0.48 / 0.08 s","elite":"0.22 / 0.08 s","note":"Raise time is the time to equip this weapon; lower time is the time to put it away. Firing cooldown can delay a switch."},{"label":"Primary sound asset","b19":"Original sound","elite":"Restored primary sound cue","note":"v1.58 restores the previously removed cue; v1.62 temporarily uses an earlier build base."},{"label":"Cooldown fill color","b19":"Original presentation","elite":"Mid-blue #15B4FF","note":"Optional HUD palette can override weapon presentation."},{"label":"Attack interactions (v1.8 policy)","b19":"Native behavior","elite":"Native projectile predicates govern rocket, Flak and Bio contacts, with reciprocal native Shock-core handling. Default rocket/core and Flak/core pairs remain ignored. Rockets and rocket grenades ignore both Weapon and WeaponNoCharacter traces on main and assist colliders; landed goo uses native shootable collision and native damage response. Other Shock exclusions remain.","note":"Contact predicates, component collision and damage response are separate gates."},{"label":"Weapon icon defaults","b19":"Original colors","elite":"Explicit Elite10K colors restored","note":"Independent HUD palettes can override presentation."},{"label":"Ready pulse","b19":"Native behavior","elite":"Finite ready pulse; original v1.93 blue styling","note":"Discrete debt-weighted sections deplete and replenish from the outside inward. Sections indicate recovery progress, not individually usable rounds."},{"label":"Regular fallback recovery","b19":"Native behavior","elite":"Frozen while continuous fallback fires; no added fallback debt","note":"Each actual secondary shot pauses recovery. Continuous held fire shows no provisional partial refill. Earlier additive fallback multipliers and ideal continuous-refill predictions no longer apply."},{"label":"Primary-fire recovery","b19":"Native behavior","elite":"Remaining debt frozen until native primary fire ends","note":"Preserves genuine quiet-time credit earned before primary fire. Primary time is never credited later; primary adds no secondary debt."},{"label":"Partial bursts and re-presses","b19":"Native behavior","elite":"Positive prefix cooldown with native scheduling","note":"Native partial timing floors and quick re-press continuation are retained. No custom re-press gate, forced spin reset or reserve queue."}],"notes":["The configured opening remains 10 shots over approximately 0.379 game seconds; actual native frame scheduling can spread the shots further apart.","Positive prefix cooldown uses the existing native cadence; the full recovery target is 0.475 game seconds. Every actual secondary shot freezes recovery.","Quiet is confirmed after the dynamic expected next-shot interval and one additional update. Recovery then counts quiet time back to the last actual secondary shot. Continuous fallback neither adds debt nor displays provisional replenishment.","Primary firing freezes the remaining recovery debt until its native firing state ends. Switching does not erase outstanding recovery.","Native scheduling, refire and spread are retained. The old additive fallback model and custom tap/reserve gates are superseded.","Discrete debt-weighted outside-in refill retains v1.93 styling. Final rendered-client, multiplayer prediction and packet-loss acceptance remain pending."],"lab":"stinger"},{"id":"bio","name":"Bio Rifle","tag":"Goo tuning","summary":"Less damage from normal and rapid goo, with a slightly slower large glob.","rows":[{"label":"Normal primary damage","b19":"40","elite":"35","note":""},{"label":"Rapid mini-goo damage","b19":"20","elite":"13","note":"Each small glob deals 13 damage before armor or amplification."},{"label":"Normal fire interval","b19":"0.30 s","elite":"0.30 s","note":""},{"label":"Rapid mini-goo firing interval","b19":"0.120 s","elite":"0.120 s","note":"Squeeze fire (primary while holding secondary): 8.33 shots/s. SqueezeFireInterval is separate from the normal 0.30-second primary interval. Game seconds at the default fire-rate multiplier."},{"label":"Secondary interval","b19":"0.35 s","elite":"0.35 s","note":""},{"label":"Large glob initial speed","b19":"≈9.33 dodge lengths/s (6,500 UU/s)","elite":"≈8.87 dodge lengths/s (6,175 UU/s)","note":"95% of B19."},{"label":"Large glob maximum speed","b19":"≈14.07 dodge lengths/s (9,800 UU/s)","elite":"≈13.37 dodge lengths/s (9,310 UU/s)","note":""},{"label":"Large glob damage parameters","b19":"Base 18 / minimum 60","elite":"Base 18 / minimum 60","note":"Strength and native charged-goo rules still apply."},{"label":"Weapon raise / lower time","b19":"0.48 / 0.08 s","elite":"0.41 / 0.08 s","note":"Raise time is the time to equip this weapon; lower time is the time to put it away. Firing cooldown can delay a switch."},{"label":"Attack interactions (v1.8 policy)","b19":"Native behavior","elite":"Native projectile predicates govern rocket, Flak and Bio contacts, with reciprocal native Shock-core handling. Default rocket/core and Flak/core pairs remain ignored. Rockets and rocket grenades ignore both Weapon and WeaponNoCharacter traces on main and assist colliders; landed goo uses native shootable collision and native damage response. Other Shock exclusions remain.","note":"Contact predicates, component collision and damage response are separate gates."},{"label":"Weapon icon defaults","b19":"Original colors","elite":"Explicit Elite10K colors restored","note":"Independent HUD palettes can override presentation."},{"label":"Landed goo interactions","b19":"Native behavior","elite":"Native shootable collision and damage handling","note":"Rocket/core flight contacts and rocket splash can remove live landed normal/large goo. Mini-goo already shuts down natively on landing. Native rules, range and damage gates apply."}],"notes":["Normal goo deals 35 instead of 40; rapid mini goo deals 13 instead of 20. Firing intervals match B19.","The large charged glob keeps its damage settings and travels at 95% of B19’s speed. Its actual damage also depends on glob strength and charged-goo rules.","Landed goo uses native landing collision rather than reapplied trace exclusions. Rocket splash and direct rocket/core contact were checked in an isolated native server; rendered/network behavior remains pending.","Bio rapid fire shoots every 0.120 s (8.33 shots/s), compared with Link primary every 0.124 s (8.06 shots/s): Bio fires about 3.3% faster, with 4 ms less between shots. Configured game-time cadence; native frame scheduling can affect actual shot times."],"lab":"bio"},{"id":"link","name":"Link Gun","tag":"No heat","summary":"Lower plasma damage, a continuous beam, and a cleaner green visual.","rows":[{"label":"Primary projectile damage","b19":"20","elite":"17","note":""},{"label":"Primary interval","b19":"0.124 s","elite":"0.124 s","note":""},{"label":"Primary initial / maximum speed","b19":"≈13.21 / 14.22 dodge lengths/s (9,200 / 9,900 UU/s)","elite":"≈13.21 / 14.22 dodge lengths/s (9,200 / 9,900 UU/s)","note":""},{"label":"Beam damage per tick","b19":"28","elite":"28","note":""},{"label":"Beam tick interval","b19":"0.23 s","elite":"0.23 s","note":""},{"label":"Beam range","b19":"≈3.37 dodge lengths (2,350 UU)","elite":"≈3.37 dodge lengths (2,350 UU)","note":""},{"label":"Pull warmup","b19":"0.085 s","elite":"0.085 s","note":""},{"label":"Pull ammo cost","b19":"3","elite":"3","note":""},{"label":"Weapon raise / lower time","b19":"0.22 / 0.08 s","elite":"0.22 / 0.08 s","note":"Raise time is the time to equip this weapon; lower time is the time to put it away. Firing cooldown can delay a switch."},{"label":"Attack interactions (v1.8 policy)","b19":"Native behavior","elite":"Native projectile predicates govern rocket, Flak and Bio contacts, with reciprocal native Shock-core handling. Default rocket/core and Flak/core pairs remain ignored. Rockets and rocket grenades ignore both Weapon and WeaponNoCharacter traces on main and assist colliders; landed goo uses native shootable collision and native damage response. Other Shock exclusions remain.","note":"Contact predicates, component collision and damage response are separate gates."},{"label":"Weapon icon defaults","b19":"Original colors","elite":"Explicit Elite10K colors restored","note":"Independent HUD palettes can override presentation."},{"label":"Primary overheating","b19":"Native behavior","elite":"Disabled","note":"Existing weapon tick resets native heat; generic crosshair hides heat-box presentation. The removed helper is not required."},{"label":"Primary projectile core appearance","b19":"Native behavior","elite":"White emissive endpoint 0.6; core opacity 1.0","note":"Highlight exponent 2 retained. Material brightness and particle opacity are separate parameters; gameplay and other effects unchanged. Final appearance pending in-game verification."}],"notes":["Primary plasma deals 17 instead of 20, with the same firing interval and projectile speeds as B19.","Beam damage, tick interval, range and pull settings match B19. Elite10K keeps the primary/beam/pull roles and omits the heat bar.","Plasma is green with a restrained white center for visibility.","Ammo supply: maximum 135, normal weapon pickup 90, normal ammo pickup 45. Pickups cap at 135. Link ammo pickup replacement scales the original map amount by 1.125, rounded; other ammo types are unchanged. Dropped weapons can carry their remaining ammunition.","Ammo consumption: primary remains 1 per shot; beam secondary remains 2 per configured 0.23-second interval; a successful pull costs 3 additional ammo. Neither firing cost nor cadence changed.","Bio rapid fire shoots every 0.120 s (8.33 shots/s), compared with Link primary every 0.124 s (8.06 shots/s): Bio fires about 3.3% faster, with 4 ms less between shots. Configured game-time cadence; native frame scheduling can affect actual shot times."],"lab":"link"},{"id":"sniper","name":"Sniper Rifle","tag":"7.5-UU trace · 1.15× head","summary":"70 body / 140 headshot damage, 7.5-UU trace radius and 1.15× headshot radius in all four shooter states.","rows":[{"label":"Normal fire model","stock":"Instant hitscan","utplus":"Instant hitscan","ncp":"Instant hitscan","b19":"Instant hitscan","elite":"Instant hitscan","note":"A zero-width line still hits the player capsule; zero added trace thickness does not mean a zero-size player hitbox."},{"label":"Body damage","b19":"70","elite":"70","note":"","stock":"65","utplus":"70","ncp":"70"},{"label":"Headshot damage","b19":"140","elite":"140","note":"","stock":"125","utplus":"125","ncp":"125"},{"label":"Firing interval","b19":"1.36 s","elite":"1.36 s","note":"","stock":"1.30 s","utplus":"1.30 s","ncp":"1.30 s"},{"label":"Trace half-size","b19":"15 UU","elite":"7.5 UU","note":"Added body-hit allowance per side of the aim line. This is separate from the headshot sphere. Both packaged rifle defaults and their replicated trace-controller defaults are 7.5 UU.","stock":"0 UU · line trace","utplus":"0 UU · line trace","ncp":"0 UU · line trace"},{"label":"Full normal-shot thickness","b19":"30 UU","elite":"15 UU added","note":"","stock":"0 UU added · line trace","utplus":"0 UU added · line trace","ncp":"0 UU added · line trace"},{"label":"Effective body-hit width · 80-UU target example","b19":"110 UU · 137.5% of Stock","elite":"95 UU · 118.75% of line trace","note":"80 + 2 × 7.5 = 95 UU. This is 86.36% of B19 Sniper’s 110-UU effective width; it is an illustrative body capsule, not headshot area or hit probability.","stock":"80 UU · 100% of Stock","utplus":"80 UU · 100% of Stock","ncp":"80 UU · 100% of Stock"},{"label":"Shot momentum","b19":"20,000","elite":"0","note":"","stock":"20,000","utplus":"0","ncp":"0"},{"label":"Trace range","b19":"≈143.6 dodge lengths (100,000 UU)","elite":"≈143.6 dodge lengths (100,000 UU)","note":"","stock":"100,000 UU","utplus":"100,000 UU","ncp":"100,000 UU"},{"label":"Weapon raise / lower time","b19":"0.41 / 0.08 s","elite":"0.41 / 0.08 s","note":"Raise time is the time to equip this weapon; lower time is the time to put it away. Firing cooldown can delay a switch.","stock":"0.45 / 0.40 s","utplus":"0.30 / 0.30 s","ncp":"0.30 / 0.30 s"},{"label":"Sniper overlay asset","b19":"Original overlay","stock":"Original overlay","utplus":"Original overlay","ncp":"Original overlay","elite":"Restored overlay asset","note":"v1.58 restores the packaged overlay."},{"label":"Attack interactions (v1.8 policy)","b19":"Native behavior","stock":"Native behavior","utplus":"Native behavior","ncp":"Native behavior","elite":"Native projectile predicates govern rocket, Flak and Bio contacts, with reciprocal native Shock-core handling. Default rocket/core and Flak/core pairs remain ignored. Rockets and rocket grenades ignore both Weapon and WeaponNoCharacter traces on main and assist colliders; landed goo uses native shootable collision and native damage response. Other Shock exclusions remain.","note":"Contact predicates, component collision and damage response are separate gates."},{"label":"Weapon icon defaults","b19":"Original colors","stock":"Original colors","utplus":"Original colors","ncp":"Original colors","elite":"Explicit Elite10K colors restored","note":"Independent HUD palettes can override presentation."},{"label":"Headshot radius scale · shooter stopped","b19":"1.65×","stock":"1.4×","utplus":"1.1×","ncp":"0.95×","elite":"1.15×","note":"Selected by the shooter’s movement state, not the victim’s. All four 10K defaults now match B19 aimed/running (1.15×); B19 stopped/slow remain 1.65×."},{"label":"Headshot radius scale · shooter slow","b19":"1.65×","stock":"1.4×","utplus":"1.1×","ncp":"0.95×","elite":"1.15×","note":"Selected by the shooter’s movement state, not the victim’s. All four 10K defaults now match B19 aimed/running (1.15×); B19 stopped/slow remain 1.65×."},{"label":"Headshot radius scale · shooter aimed","b19":"1.15×","stock":"1×","utplus":"1.1×","ncp":"0.95×","elite":"1.15×","note":"Selected by the shooter’s movement state, not the victim’s. All four 10K defaults now match B19 aimed/running (1.15×); B19 stopped/slow remain 1.65×."},{"label":"Headshot radius scale · shooter running","b19":"1.15×","stock":"1×","utplus":"1.1×","ncp":"0.95×","elite":"1.15×","note":"Selected by the shooter’s movement state, not the victim’s. All four 10K defaults now match B19 aimed/running (1.15×); B19 stopped/slow remain 1.65×."},{"label":"Headshot geometry","b19":"Separate scaled head-sphere test","stock":"Separate scaled head-sphere test","utplus":"Separate scaled head-sphere test","ncp":"Separate scaled head-sphere test","elite":"Separate scaled head-sphere test","note":"Weapon headshot scales do not change the body capsule or add trace thickness."},{"label":"Effective front-on area · 80×216 UU example","b19":"24,463 UU² · 153.8% of line-trace example","stock":"15,907 UU² · 100.0% of line-trace example","utplus":"15,907 UU² · 100.0% of line-trace example","ncp":"15,907 UU² · 100.0% of line-trace example","elite":"20,008 UU² · 125.8% of line-trace example","note":"Illustrative expanded capsule using the same geometry as the body diagram; not headshot area or hit probability."},{"label":"Effective 3D capsule surface · same example","b19":"85,011 UU² · 156.6% of line-trace example","stock":"54,287 UU² · 100.0% of line-trace example","utplus":"54,287 UU² · 100.0% of line-trace example","ncp":"54,287 UU² · 100.0% of line-trace example","elite":"68,942 UU² · 127.0% of line-trace example","note":"Illustrative expanded capsule using the same geometry as the body diagram; not headshot area or hit probability."}],"notes":["Normal hitscan has 7.5 UU of added allowance per side (15 UU full thickness). Body/headshot damage remains 70/140; firing interval remains 1.36 game seconds.","All four headshot radius scales are 1.15×: stopped, slow, aimed and running. These are the shooter’s states. Victim movement does not select the weapon multiplier.","B19 uses 1.65× for stopped/slow and 1.15× for aimed/running. Therefore 10K matches B19 aimed/running, while its stopped/slow head radius is about 30.3% smaller. B19’s extra stationary head allowance is not retained.","Compared with the previous 1.2× 10K setting, the configured head radius is 4.17% smaller. This does not reduce 140 headshot damage or change the body capsule.","For an illustrative 80-UU body capsule, the effective body-hit width is 95 UU: 80 + 2 × 7.5. B19 Sniper’s 15-UU trace gives 110 UU; 10K is 86.36% as wide in this example. These are body-hit allowances, not headshot area or hit probability.","Stock, UT+ and NCP Sniper use zero added trace thickness; a line trace still hits the full target capsule. Headshot eligibility, obstruction and server overrides remain separate.","The sniper tracer and lingering smoky streak are unchanged: original yellow effect, smoke length, lifetime, opacity and native fade."],"lab":"sniper","comparisonColumns":[{"key":"stock","label":"Stock UT"},{"key":"utplus","label":"UT+"},{"key":"ncp","label":"NCP"},{"key":"b19","label":"Original B19"},{"key":"elite","label":"Elite10K v2.02"}],"variantScope":"Profiles: Stock BP_Sniper / BP_LightningRifle; standard UT+Sniper25 / UT+LightningGun; competitive NCP UTNPSniper / UTNPLightningGun. NCP means the competitive replacement profile, not NCStockWeapons’ stock-mode option. Server overrides and alternate UT+ presets can differ."},{"id":"lightning","name":"Lightning Rifle","tag":"Hitscan replacement","summary":"70 normal / 85 charged body damage, 7.5-UU hitscan trace; headshots disabled with zero headshot size parameters.","rows":[{"label":"Map weapon replacement","b19":"Stock map weapon","elite":"Elite10K Lightning Rifle","note":"","stock":"Stock Lightning Rifle","utplus":"UT+ Lightning Gun","ncp":"NCP Lightning Gun"},{"label":"Normal fire model","b19":"Stock projectile primary","elite":"Instant hitscan","note":"","stock":"Projectile","utplus":"Instant hitscan","ncp":"Instant hitscan"},{"label":"Normal damage","b19":"Stock projectile rules","elite":"70","note":"","stock":"Projectile damage rules","utplus":"70","ncp":"70"},{"label":"Normal firing interval","b19":"0.90 s in stock parent","elite":"1.36 s","note":"","stock":"0.90 s","utplus":"1.30 s","ncp":"1.30 s"},{"label":"Normal shot trace half-size","b19":"Projectile primary","elite":"7.5 UU · 50% of B19 Sniper","note":"7.5 UU added per side gives 15 UU full trace thickness, half of B19 Sniper’s 30 UU. B19 Lightning’s normal shot is a projectile, so this width comparison uses B19 Sniper.","stock":"Projectile; not a hitscan trace","utplus":"0 UU · line trace","ncp":"0 UU · line trace"},{"label":"Full normal-shot thickness","b19":"Projectile primary; no hitscan width","elite":"15 UU added","note":"","stock":"Projectile; separate collision rules","utplus":"0 UU added · line trace","ncp":"0 UU added · line trace"},{"label":"Effective body-hit width · 80-UU target example","b19":"Projectile; separate collision rules","elite":"95 UU · 118.75% of line trace","note":"80 + 2 × 7.5 = 95 UU. This is 86.36% of B19 Sniper’s 110-UU effective width; it is an illustrative body capsule, not headshot area or hit probability.","stock":"Projectile; separate collision rules","utplus":"80 UU · 100% of line-trace example","ncp":"80 UU · 100% of line-trace example"},{"label":"Charged body / headshot","b19":"Stock charged behavior","elite":"85 body / headshots disabled","note":"A shot through the head uses ordinary charged body damage; the dormant 140 headshot-damage value is not an active damage mode.","stock":"85 / 125","utplus":"No charged shot; zoom only","ncp":"No charged shot; zoom only"},{"label":"Charged refire interval","b19":"Stock charged behavior","elite":"1.66 s","note":"","stock":"Charge-dependent; 0.90 s base interval","utplus":"Not applicable; zoom only","ncp":"Not applicable; zoom only"},{"label":"Weapon raise / lower time","b19":"Stock map weapon","elite":"0.41 / 0.08 s","note":"Raise time is the time to equip this weapon; lower time is the time to put it away. Firing cooldown can delay a switch.","stock":"0.50 / 0.40 s","utplus":"0.30 / 0.30 s","ncp":"0.30 / 0.30 s"},{"label":"Charged beam trace half-size / full thickness","stock":"5 / 10 UU","utplus":"No charged beam","ncp":"No charged beam","b19":"5 / 10 UU","elite":"7.5 / 15 UU","note":"The charged beam shares the same 7.5-UU trace allowance as normal 10K Lightning. Stock/B19 charged beam is 5/10 UU; the normal Stock/B19 shot is a projectile."},{"label":"Trace half-size","b19":"Native behavior","stock":"Native behavior","utplus":"Native behavior","ncp":"Native behavior","elite":"7.5 UU","note":"Added body-hit allowance per side of the aim line. This is separate from the headshot sphere. Both packaged rifle defaults and their replicated trace-controller defaults are 7.5 UU."},{"label":"Attack interactions (v1.8 policy)","b19":"Native behavior","stock":"Native behavior","utplus":"Native behavior","ncp":"Native behavior","elite":"Native projectile predicates govern rocket, Flak and Bio contacts, with reciprocal native Shock-core handling. Default rocket/core and Flak/core pairs remain ignored. Rockets and rocket grenades ignore both Weapon and WeaponNoCharacter traces on main and assist colliders; landed goo uses native shootable collision and native damage response. Other Shock exclusions remain.","note":"Contact predicates, component collision and damage response are separate gates."},{"label":"Weapon icon defaults","b19":"Original colors","stock":"Original colors","utplus":"Original colors","ncp":"Original colors","elite":"Explicit Elite10K colors restored","note":"Independent HUD palettes can override presentation."},{"label":"Headshot radius scale · shooter stopped","b19":"1.4×","stock":"1.4×","utplus":"1.1×","ncp":"0.95×","elite":"0× · disabled","note":"All four existing headshot size parameters are zero. The native head-sphere test cannot accept a zero-radius sphere; normal and charged body damage remain unchanged."},{"label":"Headshot radius scale · shooter slow","b19":"1.4×","stock":"1.4×","utplus":"1.1×","ncp":"0.95×","elite":"0× · disabled","note":"All four existing headshot size parameters are zero. The native head-sphere test cannot accept a zero-radius sphere; normal and charged body damage remain unchanged."},{"label":"Headshot radius scale · shooter aimed","b19":"1×","stock":"1×","utplus":"1.1×","ncp":"0.95×","elite":"0× · disabled","note":"All four existing headshot size parameters are zero. The native head-sphere test cannot accept a zero-radius sphere; normal and charged body damage remain unchanged."},{"label":"Headshot radius scale · shooter running","b19":"1×","stock":"1×","utplus":"1.1×","ncp":"0.95×","elite":"0× · disabled","note":"All four existing headshot size parameters are zero. The native head-sphere test cannot accept a zero-radius sphere; normal and charged body damage remain unchanged."},{"label":"Headshot geometry","b19":"Separate scaled head-sphere test","stock":"Separate scaled head-sphere test","utplus":"Separate scaled head-sphere test","ncp":"Separate scaled head-sphere test","elite":"Disabled · zero-radius head test","note":"Parameter-only change to Stopped/Slow/Aimed/RunningHeadshotScale. No firing code replacement; charge and native chain behavior are preserved."},{"label":"Effective front-on area · 80×216 UU example","b19":"Charged beam only: 18,602 UU² · 116.9% of line-trace example","stock":"Charged beam only: 18,602 UU² · 116.9% of line-trace example","utplus":"15,907 UU² · 100.0% of line-trace example","ncp":"15,907 UU² · 100.0% of line-trace example","elite":"20,008 UU² · 125.8% of line-trace example","note":"Illustrative expanded capsule using the same geometry as the body diagram; not headshot area or hit probability."},{"label":"Effective 3D capsule surface · same example","b19":"Charged beam only: 63,900 UU² · 117.7% of line-trace example","stock":"Charged beam only: 63,900 UU² · 117.7% of line-trace example","utplus":"54,287 UU² · 100.0% of line-trace example","ncp":"54,287 UU² · 100.0% of line-trace example","elite":"68,942 UU² · 127.0% of line-trace example","note":"Illustrative expanded capsule using the same geometry as the body diagram; not headshot area or hit probability."},{"label":"Headshot damage","b19":"125","stock":"125","utplus":"No charged shot","ncp":"No charged shot","elite":"Disabled","note":"The stored 140 value remains dormant because every headshot radius scale is zero."},{"label":"Native headshot eligibility","b19":"Fully powered charged shot","stock":"Fully powered charged shot","utplus":"No charged shot; zoom only","ncp":"No charged shot; zoom only","elite":"No eligible headshot at zero scale","note":"Fully charging still gives the native charged body/chain behavior, but no headshot bonus or headshot classification."},{"label":"Charged chain radius","stock":"800 UU · native chain","utplus":"No charged shot; zoom only","ncp":"No charged shot; zoom only","b19":"800 UU · native chain","elite":"800 UU from hit location","note":"Nearby eligible targets must pass the native visibility and target checks. This is charged chain damage, not a conventional explosive splash profile. The radius is unchanged by headshot removal."}],"notes":["Headshots are disabled. Normal and charged direct hits retain 70 and 85 body damage, including shots aimed at the head.","All four existing headshot radius multipliers are zero. This disables the separate native head-sphere acceptance test; it does not shrink the body capsule or the 7.5-UU shot trace.","Charge timing and native chain damage are preserved. Charged chaining searches up to 800 UU from the hit location (about 1.14 of the 700-UU tuning dodge distances); visibility and native eligibility still matter.","The area effect is charged chain damage to nearby targets, rather than ordinary explosive splash. Removing headshots does not remove charging or the charged body-damage bonus.","Earlier releases shown in the version selector can still have charged Lightning headshots. This installed v2.0 revision uses zero headshot scales."],"lab":null,"comparisonColumns":[{"key":"stock","label":"Stock UT"},{"key":"utplus","label":"UT+"},{"key":"ncp","label":"NCP"},{"key":"b19","label":"Original B19"},{"key":"elite","label":"Elite10K v2.02"}],"variantScope":"Profiles: Stock BP_Sniper / BP_LightningRifle; standard UT+Sniper25 / UT+LightningGun; competitive NCP UTNPSniper / UTNPLightningGun. NCP means the competitive replacement profile, not NCStockWeapons’ stock-mode option. Server overrides and alternate UT+ presets can differ."},{"id":"hammer","name":"Impact Hammer","tag":"Charge feedback","summary":"Full damage charge at 1.8 game seconds, with the existing charge and mobility feedback.","rows":[{"label":"Full damage charge time","b19":"2.00 s","elite":"1.80 s","note":""},{"label":"Full impact/jump charge fraction","b19":"25%","elite":"27.7778%","note":"Full damage charge remains 1.80 s; jump readiness is 0.50 s."},{"label":"Full impact/jump charge time","b19":"0.50 s","elite":"0.50 s","note":"Restored in the final v1.85 revision."},{"label":"Stored primary hit damage","b19":"140","elite":"140","note":""},{"label":"Primary / secondary intervals","b19":"0.20 / 0.88 s","elite":"0.20 / 0.66 s","note":"Secondary refire interval reduced 25% from B19’s 0.88 seconds."},{"label":"Weapon raise / lower time","b19":"0.115 / 0.07 s","elite":"0.115 / 0.08 s","note":"Raise time is the time to equip this weapon; lower time is the time to put it away. Firing cooldown can delay a switch."},{"label":"Alt shield blocking size","b19":"100% stock shield","elite":"115% width and height","note":"Visible shield mesh matches the 15% larger blocking coverage. Shield depth is unchanged."},{"label":"Halo color join","b19":"Original halo","elite":"Feathered red/gold join","note":"Weapon-owned HUD material; gameplay unchanged."},{"label":"Attack interactions (v1.8 policy)","b19":"Native behavior","elite":"Native projectile predicates govern rocket, Flak and Bio contacts, with reciprocal native Shock-core handling. Default rocket/core and Flak/core pairs remain ignored. Rockets and rocket grenades ignore both Weapon and WeaponNoCharacter traces on main and assist colliders; landed goo uses native shootable collision and native damage response. Other Shock exclusions remain.","note":"Contact predicates, component collision and damage response are separate gates."},{"label":"Weapon icon defaults","b19":"Original colors","elite":"Explicit Elite10K colors restored","note":"Independent HUD palettes can override presentation."},{"label":"Alt shield active duration","b19":"0.50 s","elite":"0.75 s","note":"Lifetime of each shield in game seconds. Secondary refire remains 0.66 s."}],"notes":["Full damage charge takes 1.8 game seconds; B19 takes 2.00 seconds.","Full impact/jump readiness is 0.50 game seconds; full damage charge remains 1.80 seconds.","The weapon-owned charge HUD reads the native full-charge duration and follows this timing.","Each alt-fire shield stays active for 0.75 game seconds, increased from 0.50. Secondary refire remains 0.66 game seconds."],"lab":"hammer"},{"id":"enforcer","name":"Enforcer","tag":"Core tuning retained","summary":"B19 damage and firing cadence, with a longer equip time.","rows":[{"label":"Damage per shot","b19":"20","elite":"20","note":""},{"label":"Primary interval","b19":"0.31 s","elite":"0.31 s","note":""},{"label":"Secondary interval","b19":"0.85 s","elite":"0.85 s","note":""},{"label":"Ammo costs / primary, secondary","b19":"1 / 3","elite":"1 / 3","note":""},{"label":"Trace range","b19":"≈35.9 dodge lengths (25,000 UU)","elite":"≈35.9 dodge lengths (25,000 UU)","note":""},{"label":"Trace half-size","b19":"0","elite":"0","note":""},{"label":"Weapon raise / lower time","b19":"0.26 / 0.08 s","elite":"0.41 / 0.08 s","note":"Raise time is the time to equip this weapon; lower time is the time to put it away. Firing cooldown can delay a switch."},{"label":"Attack interactions (v1.8 policy)","b19":"Native behavior","elite":"Native projectile predicates govern rocket, Flak and Bio contacts, with reciprocal native Shock-core handling. Default rocket/core and Flak/core pairs remain ignored. Rockets and rocket grenades ignore both Weapon and WeaponNoCharacter traces on main and assist colliders; landed goo uses native shootable collision and native damage response. Other Shock exclusions remain.","note":"Contact predicates, component collision and damage response are separate gates."},{"label":"Weapon icon defaults","b19":"Original colors","elite":"Explicit Elite10K colors restored","note":"Independent HUD palettes can override presentation."}],"notes":["Damage, primary/secondary firing intervals, ammo costs and trace range match B19. Equipping the Enforcer takes 0.41 seconds instead of 0.26.","The shot trace has no added width in either version. The 10K display name does not indicate a separate accuracy bonus."],"lab":"enforcer"},{"id":"grenade","name":"Grenade Launcher","tag":"Native splash","summary":"35 minimum native splash damage with 248-UU outer radius.","rows":[{"label":"Primary / secondary intervals","b19":"0.94 / 1.00 s","elite":"0.94 / 1.00 s","note":""},{"label":"Splash damage / blast radii","b19":"90 max / 20 min · 50–300 UU","elite":"90 max / 35 min · 50–248 UU","note":"Native linear splash."},{"label":"Weapon raise / lower time","b19":"0.51 / 0.08 s","elite":"0.41 / 0.08 s","note":"Raise time is the time to equip this weapon; lower time is the time to put it away. Firing cooldown can delay a switch."},{"label":"Explosion handling","b19":"Native explosion","elite":"Native explosion path","note":"Legacy projectile cutoff is disabled."},{"label":"Attack interactions (v1.8 policy)","b19":"Native behavior","elite":"Native projectile predicates govern rocket, Flak and Bio contacts, with reciprocal native Shock-core handling. Default rocket/core and Flak/core pairs remain ignored. Rockets and rocket grenades ignore both Weapon and WeaponNoCharacter traces on main and assist colliders; landed goo uses native shootable collision and native damage response. Other Shock exclusions remain.","note":"Contact predicates, component collision and damage response are separate gates."},{"label":"Weapon icon defaults","b19":"Original colors","elite":"Explicit Elite10K colors restored","note":"Independent HUD palettes can override presentation."}],"notes":["Primary/secondary intervals remain 0.94/1.00 game seconds.","Native splash: 90 max, 35 minimum, 50/248 UU inner/outer radii. Values are before armor and other modifiers.","Normal and sticky grenade profiles use the same radial parameters. Cover, armor, amplification and collision can change actual damage."],"lab":"grenade"},{"id":"redeemer","name":"Redeemer","tag":"Stock slot retained","summary":"The Redeemer keeps its stock weapon behavior in both versions.","rows":[{"label":"Weapon in this slot","b19":"Stock Redeemer","elite":"Stock Redeemer","note":"No Redeemer-specific damage rebalance in either package."},{"label":"Attack interactions (v1.8 policy)","b19":"Native behavior","elite":"Native projectile predicates govern rocket, Flak and Bio contacts, with reciprocal native Shock-core handling. Default rocket/core and Flak/core pairs remain ignored. Rockets and rocket grenades ignore both Weapon and WeaponNoCharacter traces on main and assist colliders; landed goo uses native shootable collision and native damage response. Other Shock exclusions remain.","note":"Contact predicates, component collision and damage response are separate gates."},{"label":"Weapon icon defaults","b19":"Original colors","elite":"Explicit Elite10K colors restored","note":"Independent HUD palettes can override presentation."}],"notes":["Play the Redeemer as you would in B19. This slot retains the stock weapon."],"lab":null}],"shared":[{"id":"movement","name":"Movement & interactions","tag":"Shared rules","summary":"Compare acceleration, stopping and a 180° reversal: Stock / NCP / B19, UT+, and 10K.","rows":[{"label":"Ground-dodge reset delay","b19":"0.35 s","elite":"0.01 s","note":"","stock":"0.35 s","utplus":"0.35 s","ncp":"0.35 s"},{"label":"Wall-dodge reset delay","b19":"0.20 s","elite":"0.01 s","note":"","stock":"0.20 s","utplus":"0.20 s","ncp":"0.20 s"},{"label":"Dodge-jump reset delay","b19":"0.35 s","elite":"0.01 s","note":"DodgeJumpResetInterval: stock/B19 0.35 game seconds, 10K 0.01. This cooldown does not itself enable dodge-jumping; movement-state restrictions, airtime and slide/landing behavior still apply.","stock":"0.35 s","utplus":"0.35 s","ncp":"0.35 s"},{"label":"Ground acceleration","b19":"3,200 UU/s²","elite":"5,000 UU/s²","note":"MaxAcceleration: v2.01, final v2.0 and UT+ 5,000; Stock/B19 3,200 UU/s². Initial acceleration is a separate low-speed parameter.","stock":"3,200 UU/s²","utplus":"5,000 UU/s²","ncp":"3,200 UU/s²"},{"label":"Walking braking / deceleration","b19":"520 UU/s²","elite":"2,080 UU/s²","note":"v2.01 sets both active walking braking and its persistent default to 2,080 UU/s² (final v2.0: 20,000; Stock and settled UT+: 520). Braking also acts during the neutral input gap; opposite input uses directional friction and acceleration.","stock":"520 UU/s²","utplus":"520 persistent; helper assigns 2,000","ncp":"520 UU/s²"},{"label":"Ground friction","b19":"10.5","elite":"14","note":"Directional friction with movement input: stock/NCP/B19 10.5, UT+/10K14. On release, native UT substitutes BrakingFriction5 before applying its factor2; the calculator treats these cases separately.","stock":"10.5","utplus":"14","ncp":"10.5"},{"label":"Fast initial acceleration","b19":"12,000 UU/s²","elite":"48,000 UU/s²","note":"v2.02 blends from 48,000 UU/s² at rest to normal 5,000 UU/s² by 300 UU/s. Final v2.01 blends from 96,000 by 200 UU/s; v2.0 from 100,000 by 200 UU/s. Running cap remains 940 UU/s.","stock":"12,000 UU/s²","utplus":"12,000 UU/s²","ncp":"12,000 UU/s²"},{"label":"Air control / dodge-air control","b19":"0.55 / 0.41","elite":"0.7 / 0.7","note":"AirControl / DodgeAirControl: stock/B19 0.55 / 0.41; 10K 0.7 / 0.7. These are separate dimensionless control coefficients, not airspeed or percentage-speed caps.","stock":"0.55 / 0.41","utplus":"0.7 / 0.7","ncp":"0.55 / 0.41"},{"label":"Normal running speed cap","stock":"940 UU/s","utplus":"940 UU/s","ncp":"940 UU/s","b19":"940 UU/s","elite":"940 UU/s","note":"The calculator excludes automatic forward sprint. These profiles differ in how quickly velocity changes, not their normal running-speed cap."},{"label":"Low-speed boost transition","stock":"200 UU/s","utplus":"200 UU/s","ncp":"200 UU/s","b19":"200 UU/s","elite":"300 UU/s","note":"MaxFastAccelSpeed: initial acceleration blends into normal acceleration by 300 UU/s. This is a speed range, not a time delay. v2.0/v2.01 transition at 200 UU/s."},{"label":"Release braking friction / factor","stock":"5 × 2","utplus":"5 × 2","ncp":"5 × 2","b19":"5 × 2","elite":"5 × 2","note":"Native UT movement substitutes BrakingFriction when input is released; the engine then multiplies by BrakingFrictionFactor. Reversal under opposite input uses ground friction instead."}],"notes":["Ground- and wall-dodge reset delays are 0.01 seconds instead of B19’s 0.35 and 0.20. You still need to complete the relevant movement and satisfy normal ground/wall requirements.","Acceleration is strongest when starting from low speed, then blends toward normal running acceleration. Ground friction affects steering; braking slows you when you release movement input or exceed the speed limit.","Projectile interactions are adjusted to reduce accidental interception between weapons. Server mutators and saved settings can change the defaults shown here.","The B19 column now gives explicit inherited stock defaults. The authoritative original B19 package has no overrides for these six movement settings. Current stock editor and dedicated-server native constructors agree on the values shown.","Older public UT source uses 4,000 ground acceleration and 0.45 air control. Those older defaults differ from the installed stock build, whose verified values are 3,200 and 0.55. The table follows the installed build.","Use the interactive calculator above the table to compare starting, stopping and reversing. The scrubber shares one real-time clock across profiles and marks both reversal through zero and full speed in the opposite direction.","UT+ applies its movement helper periodically. Its assigned2,000 braking value is transient because native movement restores the persistent520 default. Results model settled movement rather than the exceptional helper-application frame. NCP without an optional UT+ movement mutator retains stock core ground settings.","Stock, NCP and B19 share every numeric movement setting shown, so they use one movement column and one calculator profile. Attack interactions remain separate below the movement table.","Movement implementation: Stock/B19 use native character movement; NCP uses its TeamArena subclass with inherited core scalar defaults. UT+ and 10K use owner movement inventories; 10K retains its custom values and disables the UT+ sync-config override. Matching values do not mean these implementations are identical.","v2.01 uses initial acceleration 96,000, normal acceleration 5,000 and braking 2,080 UU/s², with transition speed 200 UU/s. At 100 UU/s the acceleration is 50,500 UU/s². The graph marks each profile’s low-speed blend only while directional input is active.","v2.02 uses initial acceleration 48,000, normal 5,000 and braking 2,080 UU/s², with transition speed 300 UU/s. At 150 UU/s acceleration is 26,500 UU/s². Thicker graph segments identify each profile’s own low-speed blend while directional input is active."],"lab":null,"comparisonColumns":[{"key":"b19","label":"Stock / NCP / B19"},{"key":"utplus","label":"UT+"},{"key":"elite","label":"Elite10K v2.02"}],"comparisonStyle":"movement","variantScope":"UT+ means the UTPlus mutator and its UT+MovementInventory. NCP means the competitive TeamArena pawn without an additional UT+ movement mutator. Stacked server mutators and optional profiles can differ. The calculator uses settled normal running, with sprint excluded.","attackComparison":{"id":"movement-attacks","name":"Attack interactions","comparisonStyle":"interactions","comparisonColumns":[{"key":"stock","label":"Stock UT"},{"key":"utplus","label":"UT+"},{"key":"ncp","label":"NCP"},{"key":"b19","label":"Original B19"},{"key":"elite","label":"Elite10K v2.02"}],"rows":[{"label":"Attack interactions (v1.8 policy)","b19":"Native behavior","elite":"Native projectile predicates govern rocket, Flak and Bio contacts, with reciprocal native Shock-core handling. Default rocket/core and Flak/core pairs remain ignored. Rockets and rocket grenades ignore both Weapon and WeaponNoCharacter traces on main and assist colliders; landed goo uses native shootable collision and native damage response. Other Shock exclusions remain.","note":"Contact predicates, component collision and damage response are separate gates.","stock":"Native stock projectile rules","utplus":"UT+ profile rules; not part of this movement model","ncp":"Competitive NCP profile rules; not part of this movement model"}],"variantScope":"These attack rules are separate from the movement timings above. Matching movement values do not imply matching projectile interactions."}},{"id":"visuals","name":"HUD & readability","tag":"Visual feedback","summary":"Weapon-owned effects for this release; optional HUD versioning is separate.","rows":[{"label":"Rocket loading feedback","b19":"B19 crosshair feedback","elite":"5% smaller red rings; adjustable radius and opacity","note":"Default radius scale 1.0; maximum 1.75. Default opacity 87.5%. Either value set to exactly 0 skips custom-ring drawing while preserving native aiming and lock indicators."},{"label":"Hammer feedback","b19":"B19 weapon feedback","elite":"Charge arc and jump/damage indicators","note":"Read jump readiness separately from full damage charge."},{"label":"Stinger appearance","b19":"B19 weapon effects","elite":"Blue primary and secondary effects","note":"Cosmetic weapon identification."},{"label":"Full-screen HUD","b19":"B19 / stock HUD","elite":"Separate optional Elite10K HUD v1.18","note":"Weapons and HUD packages have independent versions."},{"label":"Firing feedback","b19":"Stock HUD presentation","elite":"Coordinated widget bounce","note":"Ammo, vitals, weapon bar, kill feed, scoreboard and announcements follow the firing impulse."},{"label":"Weapon identification","b19":"B19 weapon colors","elite":"Shared weapon-bar and kill-feed colors","note":"Shock, combo and Anticombo feed icons have a slightly lighter tint."},{"label":"Health / armor bars","b19":"B19 / stock HUD","elite":"Smooth 0.36-second fill/drain and glow","note":"Numbers update with their own brief feedback animation."},{"label":"Ammo feedback","b19":"B19 / stock HUD","elite":"Brief number pulse when held ammo increases","note":"Low-ammo warnings and unlimited-ammo infinity display are retained."},{"label":"Powerup display","b19":"Stock icons and counters","elite":"Sharper amp/boots icons and centered bold counters","note":"Antialiased artwork, consistent padding and equal-width panels."},{"label":"Match status","b19":"Stock game status","elite":"Native status wording beneath the clock","note":"Appears when the game supplies a status such as Waiting for Host or Overtime. Clock/status spacing adjusts when text is present."},{"label":"Rocket projectile art","b19":"Native behavior","elite":"Final merged shell","note":""},{"label":"Flak visible smoke opacity","b19":"Native behavior","elite":"0.2","note":""},{"label":"Weapon icon defaults","b19":"Native behavior","elite":"Explicit Elite10K colors restored","note":""},{"label":"Switch highlight timing","b19":"Native behavior","elite":"Immediate pending-weapon glow","note":"The final normal-trace v1.6 revision introduces the immediate gate; v1.62 temporarily reverts to its older build base."},{"label":"Own weapon switch glow","b19":"Original visibility","elite":"Visible in behindview 1; hidden in first person","note":"Uses the existing switch effect and timing. Other clients can receive switch state later because of network delay."},{"label":"Link primary core","b19":"Native behavior","elite":"White endpoint 0.6 / opacity 1.0","note":"Final v1.95 revision; earlier 200, 0.4, 0.8 and zero-opacity trials are superseded."},{"label":"Initial console notices","b19":"Not available in original B19","elite":"Elite10K Settings: type 10kSettings to open settings.","note":"Printed on HUD initialization. The old 10kRocketLoadRings and 10kWeaponSwitchFlash commands are removed. The redundant ring-enabled boolean is removed; old Off preferences migrate to radius 0 when no newer radius preference exists."},{"label":"Rocket loading pulse white tint","b19":"Not available in original B19","elite":"13.5% at peak pulse","note":"White mixing in the filled disk during the pulse. This is separate from overall opacity and does not change the other pulse brightness, glow or timing settings."},{"label":"Elite10K Settings","b19":"Not available in original B19","elite":"Type 10kSettings (or 10ksettings)","note":"Local visual preferences: no host or admin rights required. The command is provided by a current 10K weapon or the updated optional 10K HUD. Some early v1.98 revisions predate this menu."},{"label":"Apply and default behavior","b19":"Not available in original B19","elite":"Apply appears only for pending value changes","note":"Opening the dialog is clean. Reverting edits hides Apply. Default buttons change pending values only. Apply saves and applies; Close/Escape discard unapplied changes. Save errors retain pending edits. Applying a default removes its saved override, including manually entered or slider-selected defaults."}],"notes":["Preferences affect only your view; weapon balance, firing timing and other players are unchanged.","Native aiming and lock indicators remain visible when custom loading rings are hidden.","Joining an older server can replace the installed pak. That does not replace the preserved final development artifact or change which release this guide describes.","If 10kSettings is unrecognized, equip a 10K weapon or use the updated 10K HUD. B19/stock weapons do not provide the 10K weapon command. The visible version number alone does not distinguish early and final v1.98 packages."],"lab":null},{"id":"foundation","name":"Version & setup","tag":"Know what is running","summary":"Choose the right package and read the comparisons with your B19 experience in mind.","rows":[{"label":"Weapons compared","b19":"Original Elite Weapons B19","elite":"Elite10K v2.02 · initial 48,000 / transition 300","note":"Flak ball 94%, normal rockets 91% of B19; rifle settings unchanged."},{"label":"Optional full-screen HUD","b19":"B19 / stock HUD","elite":"Elite10K HUD v1.18, updated settings revision","note":"Independent HUD version preserved; supplies settings access and the Elite10K Settings console notice across five HUD modes."},{"label":"Damage examples","b19":"Before armor/amplification","elite":"Before armor/amplification","note":"Actual health loss depends on armor, damage boosts and server rules."},{"label":"Timing examples","b19":"Game seconds","elite":"Game seconds","note":"Game speed and fire-rate modifiers affect real elapsed time."},{"label":"Local visual preferences","b19":"Not available in original B19","elite":"Elite10K Settings or the three dotted console commands","note":"Saved on your computer in Saved/SaveGames, not Game.ini. Direct commands save/apply immediately. Preferences persist across UT restarts."}],"notes":["Installed weapons package SHA256: CBC4AD7398D9FFE25A34DFF32C6CE5AA0C9F1937EE214C4AAA77A31509C7DB52.","Original Elite B19 remains the authoritative comparison reference. Optional HUD and native client DLL are separate releases.","Server weapon replacements are separate from package defaults and are not part of the release balance shown here."],"lab":null}],"baselineSha256":"A17869BA76025E0F4FC3B9D52F37A271AF363E4760561AAB094DB82D4DD861CF","packageSha256":"CBC4AD7398D9FFE25A34DFF32C6CE5AA0C9F1937EE214C4AAA77A31509C7DB52","verifiedDate":"2026-11-16","assumptions":"Default settings; times are game seconds. Damage examples exclude armor and amplification. Stock UT means the base Unreal Tournament behavior used by B19 for that setting. Actual hits also depend on collision and line of sight.","hudVersion":"1.18","hudPackageSha256":"CEEBEE9F5C2D982D492567DB2D8B2FAD90E38822BF50945CC8526D1432298A35","shockVariantData":"shock-variants.js","revision":"v2.02: initial acceleration 48,000; normal 5,000; transition 300 UU/s; braking 2,080; Flak ball 94% / normal rockets 91% of B19","model":{"combo":{"max":210,"min":50,"inner":77,"outer":390,"falloff":1.5,"baseBoost":0},"trace":7.5,"shockInterval":0.49451,"shockSwitch":0.15,"stinger":{"shots":10,"recovery":0.475,"gaps":[0.2,0.07,0.05,0.03,0.014,0.008,0.004,0.002,0.001],"regularInterval":0.148,"recoveryDuringFallback":false,"primaryPausesRecovery":true,"heldBurstPausesRecovery":true,"shotBasedQuietConfirmation":true,"fallbackAddsDebt":false,"nativeScheduling":true,"prefixCooldown":true},"flak":{"linear":true,"start":700,"end":1400,"interval":0.9,"nativeTime":true,"delay":0.05384615436196327,"floorAge":0.10769230993629929,"speed":13000,"storedBase":[10.399999618530273,20.799999237060547],"storedMinimum":[4,8],"multiplier":1,"base":10.399999618530273,"minimum":4,"centralBase":20.799999237060547,"attenuation":118.85713195800781},"splash":{"legacy":false,"rocket":[100,35,15,296.66666],"flak":[95,35,0,240],"grenade":[90,35,50,248]},"foreignLabel":"Anticombo!","confirmedNotices":true,"rocketDeadline":false,"headshots":{"sniper":[1.15,1.15,1.15,1.15],"lightning":[0,0,0,0]},"hammer":{"full":1.8,"impactFraction":0.2777777777777778,"shieldLifetime":0.75},"shreddedAllNine":false,"shredded":{"native":true,"maxShreddedTime":0.15},"rocketNativeSwitch":true,"rocketEquip":0.41,"linkAmmo":{"maximum":135,"weaponPickup":90,"normalAmmoPickup":45,"primaryCost":1,"secondaryCost":2,"secondaryInterval":0.23,"successfulPullCost":3},"linkCore":{"whiteEndpoint":0.6,"opacity":1,"highlightExponent":2},"rocketRingScaleFromV196":0.95,"localVisualSettings":true,"rocketRingRadiusScale":{"min":0,"max":1.75,"default":1},"rocketRingOpacity":{"min":0,"max":1,"default":0.875},"rocketRingPulseWhiteTint":0.135,"earlyGrenadeRecovery":[1.05,0.895,0.74],"lightningHeadshotsEnabled":false,"flakBall":{"initialSpeed":3055,"maximumSpeed":6467.2,"percentB19":94},"groundMovement":{"profiles":[{"id":"stock","name":"Stock / NCP / B19","maxSpeed":940,"acceleration":3200,"fastAcceleration":12000,"fastThreshold":200,"friction":10.5,"braking":520,"brakeFriction":5,"brakeFactor":2,"stopThreshold":10,"groundReset":0.35,"wallReset":0.2,"dodgeJumpReset":0.35,"airControl":0.55,"dodgeAirControl":0.41},{"id":"utplus","name":"UT+","maxSpeed":940,"acceleration":5000,"fastAcceleration":12000,"fastThreshold":200,"friction":14,"braking":520,"brakeFriction":5,"brakeFactor":2,"stopThreshold":10,"groundReset":0.35,"wallReset":0.2,"dodgeJumpReset":0.35,"airControl":0.7,"dodgeAirControl":0.7,"assignedBraking":2000},{"id":"elite","name":"Elite10K","maxSpeed":940,"acceleration":5000,"fastAcceleration":48000,"fastThreshold":300,"friction":14,"braking":2080,"brakeFriction":5,"brakeFactor":2,"stopThreshold":10,"groundReset":0.01,"wallReset":0.01,"dodgeJumpReset":0.01,"airControl":0.7,"dodgeAirControl":0.7}],"dt":0.001,"scope":"Full keyboard input, flat dry ground, normal 940UU/s running, no sprint/dodge/crouch/slopes/collision/latency. NCP competitive TeamArena pawn without optional UT+ movement mutator. UT+ settled movement uses persistent520 braking after the native post-move reset; periodic helper application frames excluded."},"normalRocket":{"initialSpeed":2912,"maximumSpeed":4732,"percentB19":91,"acceleration":600}},"releaseSource":{"receipt":"elite-v2.02/initial48000-threshold300/report.json","artifact":"elite-v2.02/initial48000-threshold300/Elite10K-WindowsNoEditor.pak.pending","verification":"Verified installed client/server, full redirect download, launcher guard, HUD preservation, Pure startup and comparison pickups. Only existing initial acceleration16200->48000 and transition400->300 float literals changed. Other payloads preserved; runtime feel acceptance pending."},"comboMovement":{"id":"combo-movement","name":"Combo movement scoring","rows":[{"label":"Movement tier thresholds","b19":"Standard UT combo awards (no damage bonus)","elite":"8 / 20 / 32","note":"Elite10K scores 8/20/32 earn Nice/Amazing/Spectacular damage bonuses."},{"label":"Airborne score weighting","b19":"Speed weighting: 5 in air / 3 on ground","elite":"3 on ground and in air","note":"Controls the sideways-speed contribution to combo scoring."}],"notes":["Combo movement rewards sideways movement relative to the core’s flight. Running straight along its path contributes less than changing the angle. The score uses the same speed weighting on the ground and in the air.","Distance is shown in UU (Unreal Units) and approximate dodge lengths. One reference dodge length is about 696 UU. These describe distance, rather than how many dodge inputs to press."]},"localOptions":[{"command":"10k.rocketLoadHudRings.radiusScale","name":"Rocket Loading Rings on HUD - Radius Scale","range":"0–1.75","default":"1.0","note":"0 hides the rocket loading rings. The default preserves the final v1.98 size, 5% smaller than the pre-reduction rings. Older saved values above 1.75 clamp when loaded."},{"command":"10k.rocketLoadHudRings.opacity","name":"Rocket Loading Rings on HUD - Opacity","range":"0–1","default":"0.875 (87.5%)","note":"0 hides the rocket loading rings. Changes the actual shared material opacity for all three rings."},{"command":"10k.weaponSwitchIndicators.enabled","name":"Weapon switch indicators","range":"0 (Off) or 1 (On)","default":"1 (On)","note":"Controls your colored weapon-switch indicator; the menu uses a sliding toggle with an On/Off label."}],"settingsMenu":true,"releaseNotice":"Installed v2.02: initial acceleration 48,000 UU/s², normal 5,000 UU/s², transition 300 UU/s and braking 2,080 UU/s². Flak ball 94%, normal rockets 91% of B19. v2.0 and final v2.01 remain separately selectable.","stockMovementReference":{"verifiedDate":"2026-11-16","evidence":"stock-movement-evidence.json","method":"Native stock constructor assignments and property metadata, independently matched across editor and dedicated-server binaries; authoritative B19 package checked for overrides."}};
